import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"杨氏易传","description":"杨氏易传 - 杨氏易传","frontmatter":{"title":"杨氏易传","description":"杨氏易传 - 杨氏易传"},"headers":[],"relativePath":"zh/classics/yangshi/001.md","filePath":"zh/classics/yangshi/001.md"}'),r={name:"zh/classics/yangshi/001.md"};function i(c,a,o,p,d,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"杨氏易传",tabindex:"-1"},[l("杨氏易传 "),e("a",{class:"header-anchor",href:"#杨氏易传","aria-label":"Permalink to “杨氏易传”"},"​")],-1),e("p",null,"钦定四库全书经部一",-1),e("p",null,"易类提要",-1),e("p",null,"臣 等谨案：杨氏易传二十卷，宋杨简撰。简字敬仲，慈溪人。乾道五年进士，官至宝谟阁学士、太中大夫。是书为明刘日升、陈道亨所校刻。案朱彝尊经义考载慈湖易解十卷，又己易一卷，书名、卷数皆与此本不合。所载自序一篇，与此本卷首题语相同，而无其前数行，亦为小异。明人凡刻古书，必以私意窜乱之，万历以后尤甚。此或日升等所妄改欤？其书前十九卷皆解经文，第二十卷则皆泛论易学之语，亦间有与序文相复者。今既不睹简之原本，亦莫详其何故也。简之学出陆九渊，故其解易惟以人心为主，而象数事物皆在所略，甚至谓繋辞中「近取诸身」一节为不知道者所伪作，非孔子之言。故明杨时乔作传易考，竟斥为异端。而元董真卿论林栗易解，亦引朱子语录称「杨敬仲文字可毁」云云。岂非简之骛谈高远，有以致之乎？考自汉以来，以老庄说易者，始魏王弼；以心性说易者，始王宗传及简。宗传，淳熙中进士；简，乾道中进士，皆孝宗时人也。顾宗传人微言轻，其书仅存，不为学者所诵习。简则为象山弟子之冠，如朱门之有黄干，又历官中外，政绩卓有可观，在南宋为名臣，尤足以笼罩一世。故至于明季，其说大行。紫溪苏濬解易，遂以冥冥篇为名，而易全入禅矣。夫易之为书，广大悉备，圣人之为教，精粗本末，兼该心性之理，未尝不蕴易中。特简等专明此义，遂流于恍惚虚无耳。昔朱子作仪礼经传通解，不删郑康成所引谶纬之说，谓「存之正所以废之」。盖其名既重，不存其说，人无由知其失也。今录简及宗传之易，亦犹是义云。乾隆四十四年六月恭校上。",-1),e("p",null,"总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。杨氏易传原序",-1),e("p",null,"昨秋余入南铨选部，陈君以所刻苏长公易传相示，余读而卒业，已谓奇矣。顷之，封司刘君、功司陈君复刻杨敬仲易传成，属余叙。余读之，又一奇也。独斯传也，明所学也。余不学，其何敢序？然学不可以终弃，则传言学者不敢不致意也，叙何可已。夫易道大矣，自周、孔而后，微言绝而程朱传行，谓可以尽易，而易有所不可尽也。今观苏氏传，虽未必尽合易旨，然借易以发其自有之奇，其识隽，其文雄，往往道人所未经道，其卒传宜也。杨氏因易之理以发摅其所学，精深融贯，要在一而能通，示人专事内而不外，非直探本原者能之乎？要之，苏即事以明理，杨溯源以该流。譬之苏如樝梨橘柚杂陈而皆适于口，杨则即一樝梨橘柚，而凡为樝梨橘柚之类者，皆可推而味之也。是二氏俱深于易，求其有补于学，杨视苏为要焉。抑杨氏始因象山先生举扇柄而得其本心，遂悟所学，乃发为易传，于乾有曰：「君子自强不息者，即天行之健也，非天行之健在彼，而君子效之于此也。」又曰：「子思不曰诚者自诚，而曰自成，是于诚实之外复起自成之意，失其诚矣。」斯语也，亦犹是心也。唯是健不必效，而诚不必成，或疑允若兹，是人皆天也，不必复益以人力也，不几于溺人以虚乎？然善语道者必反其本，善察言者必抉其要。慈湖先生尝云：「少读易大传，唯爱无思也，无为也，寂然不动，感而遂通天下之故。故其传益，则以善之不能为，过之难改，皆始于意。意本于我，知我本无体，复何迁而何改？」传震又曰：人唯知恐惧修省，学者事耳，谓易道精微不在是。持是见者，不惟不知易，亦不知恐惧修省。夫曰「不能为」，曰「难改」，曰「恐惧修省」，则何尝不责人之致力，特其所以致者，在何思何虑而不失其寂然者耳。盖用力于其本，而不泛用者也。譬之操舟者然，顺流帆风，楫櫂随之，瞬息千里，是不操之操，操更力耳。庸可以无操之迹，遂谓其不操舟也？审然者，不惟益易，且益学者哉！吁！此与苏传均易之羽翼也，顾湮没久矣，待三君而始传，信大宝之显晦有时哉！然一时并显，而三君与诸同官之志于易，及易道之益明可觇矣。独愧余莫为倡，其独无入山舍玉之惧乎？兹叙也，并以自勖云。蔡国珍序。",-1)])])}const _=s(r,[["render",i]]);export{u as __pageData,_ as default};
